   148	it('applies exact patched files from every temporary-directory Git context', function (string $context): void {
   149	    $fixture = pestSetupFixture();
   150	    $container = temporaryPath('orbit pest temp context ', 6);
   151	    $primary = null;
   152	
   153	    if ($context === 'outside Git') {
   154	        mkdir($container, 0700, true);
   155	        $temporaryDirectory = $container;
   156	    } elseif ($context === 'repository root') {
   157	        initializePestSetupRepository($container);
   158	        $temporaryDirectory = $container;
   159	    } elseif ($context === 'checkout subdirectory') {
   160	        initializePestSetupRepository($container);
   161	        $temporaryDirectory = $container.'/nested temp directory';
   162	        mkdir($temporaryDirectory, 0700, true);
   163	    } else {
   164	        $primary = $container;
   165	        initializePestSetupRepository($primary);
   166	        $linked = $container.' linked worktree';
   167	        new Process(['git', 'worktree', 'add', '-b', 'feature', $linked], $primary)->mustRun();
   168	        $temporaryDirectory = $linked.'/nested temp directory';
   169	        mkdir($temporaryDirectory, 0700, true);
   170	    }
   171	
   172	    try {
   173	        $result = runPestSetup($fixture, ['TMPDIR' => $temporaryDirectory]);
   174	
   175	        expect($result->isSuccessful())->toBeTrue($result->getErrorOutput());
   176	        expect($result->getWorkingDirectory())->toBe($fixture['project']);
   177	        expect($result->getEnv()['TMPDIR'])->toBe($temporaryDirectory);
   178	        expectPestSetupFiles($fixture, 'patched');
   179	    } finally {
   180	        if ($primary !== null) {
   181	            new Process(['git', 'worktree', 'remove', '--force', dirname($temporaryDirectory)], $primary)->mustRun();
   182	        }
   183	    }
   184	})->with([
   185	    'outside Git' => 'outside Git',
   186	    'repository root' => 'repository root',
   187	    'checkout subdirectory' => 'checkout subdirectory',
   188	    'linked-worktree subdirectory' => 'linked-worktree subdirectory',
   189	]);
