   191	it('changes only the selected Pest package and setup lock', function (): void {
   192	    $fixture = pestSetupFixture();
   193	    $neighbor = $fixture['root'].'/apps/neighbor';
   194	    mkdir($neighbor.'/vendor/pestphp/pest', 0700, true);
   195	    file_put_contents($neighbor.'/composer.lock', 'neighbor lock');
   196	    file_put_contents($neighbor.'/vendor/pestphp/pest/neighbor.php', 'neighbor package');
   197	    file_put_contents($fixture['project'].'/tracked sentinel.txt', 'tracked project sentinel');
   198	    file_put_contents($fixture['project'].'/untracked sentinel.txt', 'untracked project sentinel');
   199	    $before = pestSetupTreeSnapshot($fixture['root']);
   200	
   201	    $repository = temporaryPath('orbit pest enclosing repository ', 6);
   202	    initializePestSetupRepository($repository);
   203	    file_put_contents($repository.'/staged sentinel.txt', 'staged');
   204	    new Process(['git', 'add', 'staged sentinel.txt'], $repository)->mustRun();
   205	    file_put_contents($repository.'/untracked sentinel.txt', 'untracked');
   206	    $head = trim(new Process(['git', 'rev-parse', 'HEAD'], $repository)->mustRun()->getOutput());
   207	    $index = trim(new Process(['git', 'write-tree'], $repository)->mustRun()->getOutput());
   208	    $status = new Process(['git', 'status', '--porcelain=v1', '--untracked-files=all'], $repository)->mustRun()->getOutput();
   209	    $temporaryDirectory = $repository.'/temporary directory';
   210	    mkdir($temporaryDirectory, 0700, true);
   211	
   212	    $result = runPestSetup($fixture, ['TMPDIR' => $temporaryDirectory]);
   213	
   214	    expect($result->isSuccessful())->toBeTrue($result->getErrorOutput());
   215	    expectPestSetupFiles($fixture, 'patched');
   216	    $after = pestSetupTreeSnapshot($fixture['root']);
   217	    $changed = array_keys(array_diff_assoc($after, $before) + array_diff_assoc($before, $after));
   218	    $expected = array_map(
   219	        fn (string $file): string => 'linked worktree/apps/sample/vendor/pestphp/pest/'.$file,
   220	        array_keys($fixture['files']),
   221	    );
   222	    $expected[] = 'linked worktree/apps/sample/vendor/.orbit-pest-setup.lock';
   223	    sort($changed);
   224	    sort($expected);
   225	    expect($changed)->toBe($expected);
   226	    expect(trim(new Process(['git', 'rev-parse', 'HEAD'], $repository)->mustRun()->getOutput()))->toBe($head);
   227	    expect(trim(new Process(['git', 'write-tree'], $repository)->mustRun()->getOutput()))->toBe($index);
   228	    expect(new Process(['git', 'status', '--porcelain=v1', '--untracked-files=all'], $repository)->mustRun()->getOutput())->toBe($status);
   229	});
