   231	it('recovers the retained upstream package after patch execution fails and remains idempotent', function (): void {
   232	    $fixture = pestSetupFixture();
   233	    $inode = fileinode($fixture['pest']);
   234	    file_put_contents($fixture['pest'].'/package sentinel.txt', 'same package');
   235	    $shim = pestSetupGitShim('failure');
   236	
   237	    $failed = runPestSetup($fixture, [
   238	        'PATH' => $shim['PATH'],
   239	        'ORBIT_PEST_GIT_LOG' => $shim['log'],
   240	    ]);
   241	    expect($failed->getExitCode())->toBe(1);
   242	    expectPestSetupFiles($fixture, 'upstream');
   243	
   244	    $recovered = runPestSetup($fixture);
   245	    $patched = pestSetupTreeSnapshot($fixture['pest']);
   246	    $repeated = runPestSetup($fixture);
   247	
   248	    expect($recovered->isSuccessful())->toBeTrue($recovered->getErrorOutput());
   249	    expect($repeated->isSuccessful())->toBeTrue($repeated->getErrorOutput());
   250	    expect(fileinode($fixture['pest']))->toBe($inode);
   251	    expect(file_get_contents($fixture['pest'].'/package sentinel.txt'))->toBe('same package');
   252	    expect(pestSetupTreeSnapshot($fixture['pest']))->toBe($patched);
   253	    expectPestSetupFiles($fixture, 'patched');
   254	});
