   256	it('reports patch execution failures without classifying upstream files as modified', function (string $result): void {
   257	    $fixture = pestSetupFixture();
   258	    $shim = pestSetupGitShim($result);
   259	    $temporaryDirectory = temporaryPath('orbit pest injected process ', 6);
   260	    mkdir($temporaryDirectory, 0700, true);
   261	
   262	    $process = runPestSetup($fixture, [
   263	        'PATH' => $shim['PATH'],
   264	        'ORBIT_PEST_GIT_LOG' => $shim['log'],
   265	        'TMPDIR' => $temporaryDirectory,
   266	    ]);
   267	
   268	    expect($process->getExitCode())->toBe(1);
   269	    expect($process->getErrorOutput())->toContain('pinned monorepo patch');
   270	    expect($process->getErrorOutput())->toContain('retry setup without reinstalling Pest');
   271	    expect($process->getErrorOutput())->not->toContain('files differ from the pinned');
   272	    expectPestSetupFiles($fixture, 'upstream');
   273	    $arguments = file($shim['log'], FILE_IGNORE_NEW_LINES);
   274	    $checkArguments = [
   275	        'cwd='.DIRECTORY_SEPARATOR,
   276	        'tmpdir='.$temporaryDirectory,
   277	        'apply',
   278	        '--unsafe-paths',
   279	        '--directory='.$fixture['pest'],
   280	        '--check',
   281	        $fixture['patch'],
   282	    ];
   283	    $applyArguments = [
   284	        'cwd='.DIRECTORY_SEPARATOR,
   285	        'tmpdir='.$temporaryDirectory,
   286	        'apply',
   287	        '--unsafe-paths',
   288	        '--directory='.$fixture['pest'],
   289	        $fixture['patch'],
   290	    ];
   291	    expect($arguments)->toBe($result === 'failure' ? $checkArguments : [...$checkArguments, ...$applyArguments]);
   292	})->with([
   293	    'nonzero Git process' => 'failure',
   294	    'exit-zero Git process that applies nothing' => 'no-op',
   295	]);
