   297	it('refuses changed upstream files before changing any package file', function (): void {
   298	    $fixture = pestSetupFixture();
   299	    $entrypoint = file_get_contents($fixture['pest'].'/bin/pest');
   300	    file_put_contents($fixture['pest'].'/src/Plugins/Tia.php', "\nlocal edit", FILE_APPEND);
   301	
   302	    $result = runPestSetup($fixture);
   303	
   304	    expect($result->getExitCode())->toBe(1);
   305	    expect($result->getErrorOutput())->toContain('differ from the pinned');
   306	    expect(file_get_contents($fixture['pest'].'/bin/pest'))->toBe($entrypoint);
   307	    expect(file_exists($fixture['pest'].'/src/Plugins/Tia/GitRepository.php'))->toBeFalse();
   308	});
