   310	it('refuses a Pest upgrade until its patch is reviewed', function (): void {
   311	    $fixture = pestSetupFixture();
   312	    file_put_contents($fixture['project'].'/vendor/composer/installed.json', json_encode([
   313	        'packages' => [['name' => 'pestphp/pest', 'version' => 'v5.2.0']],
   314	    ], JSON_THROW_ON_ERROR));
   315	
   316	    $result = runPestSetup($fixture);
   317	
   318	    expect($result->getExitCode())->toBe(1);
   319	    expect($result->getErrorOutput())->toContain('unsupported Pest version');
   320	    expect(file_exists($fixture['pest'].'/src/Plugins/Tia/GitRepository.php'))->toBeFalse();
   321	});
