   323	it('refuses a changed pinned patch checksum from a disposable setup bundle', function (): void {
   324	    $fixture = pestSetupFixture();
   325	    $bundle = temporaryPath('orbit pest disposable bundle ', 6);
   326	    mkdir($bundle.'/pest-support', 0700, true);
   327	    copy($fixture['script'], $bundle.'/pest-setup');
   328	    copy(dirname($fixture['patch']).'/manifest.json', $bundle.'/pest-support/manifest.json');
   329	    copy($fixture['patch'], $bundle.'/pest-support/monorepo.patch');
   330	    file_put_contents($bundle.'/pest-support/monorepo.patch', "\nchanged checksum", FILE_APPEND);
   331	    $fixture['script'] = $bundle.'/pest-setup';
   332	
   333	    $result = runPestSetup($fixture);
   334	
   335	    expect($result->getExitCode())->toBe(1);
   336	    expect($result->getErrorOutput())->toContain('pinned patch checksum does not match');
   337	    expectPestSetupFiles($fixture, 'upstream');
   338	});
