   340	it('skips production installations without Pest', function (): void {
   341	    $fixture = pestSetupFixture();
   342	    file_put_contents($fixture['project'].'/vendor/composer/installed.json', '{"packages":[]}');
   343	
   344	    $result = runPestSetup($fixture);
   345	
   346	    expect($result->isSuccessful())->toBeTrue();
   347	    expect($result->getOutput())->toBe('');
   348	    expect(file_exists($fixture['pest'].'/src/Plugins/Tia/GitRepository.php'))->toBeFalse();
   349	});
   350	
   351	it('keeps an already patched local fork and refuses to mutate a linked upstream checkout', function (bool $patched): void {
   352	    $fixture = pestSetupFixture(! $patched);
   353	    $external = $fixture['project'].'/external-pest';
   354	    rename($fixture['pest'], $external);
   355	    symlink($external, $fixture['pest']);
   356	
   357	    $result = runPestSetup($fixture);
   358	
   359	    expect($result->getExitCode())->toBe($patched ? 0 : 1);
   360	    expect(file_exists($external.'/src/Plugins/Tia/GitRepository.php'))->toBe($patched);
   361	    if (! $patched) {
   362	        expect($result->getErrorOutput())->toContain('refusing to modify a linked');
   363	    }
   364	})->with([true, false]);
